 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(back);getWindow().setNavigationBarColor(back);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setFitsSystemWindows(true);root.setBackgroundColor(back);root.setPadding(dp(16),dp(10),dp(16),dp(10));setContentView(root);
 text(root,"导航同步",28,ink).setTypeface(null,1);text(root,"高德通知  /  蓝牙直连设备",14,muted);ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout content=new LinearLayout(this);content.setOrientation(1);scroll.addView(content);
 LinearLayout link=card(content,panel);state=text(link,"等待连接",20,ink);summary=text(link,"授权通知并连接蓝牙后自动同步",14,muted);forward=new Switch(this);forward.setText("自动同步导航通知");forward.setTextSize(17);forward.setTextColor(ink);link.addView(forward);forward.setChecked(NavigationNotificationService.savedEnabled(this));forward.setOnCheckedChangeListener((v,on)->{if(!updating)NavigationNotificationService.enable(this,on);});
 LinearLayout nav=card(content,0xff133938);text(nav,"当前指引",14,mint);arrow=new Arrow(this);nav.addView(arrow,new LinearLayout.LayoutParams(-1,dp(130)));distance=text(nav,"--",46,ink);distance.setTypeface(null,1);distance.setGravity(Gravity.CENTER);turn=text(nav,"等待高德导航",21,mint);turn.setGravity(Gravity.CENTER);road=text(nav,"开始导航后显示最新指引",16,ink);road.setGravity(Gravity.CENTER);remaining=text(nav,"剩余 --  ·  -- 分钟",16,muted);remaining.setGravity(Gravity.CENTER);
 LinearLayout sound=card(content,panel);text(sound,"语音与后台",19,ink);text(sound,"设备本地语音播报，跟随设备音量与勿扰设置。",14,muted);background=text(sound,"后台服务未运行",14,mint);button(sound,"开启后台运行",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},19);NavigationKeepAliveService.ensure(this);});
 LinearLayout access=card(content,panel);text(access,"通知使用权",19,ink);text(access,"仅处理高德通知，内容不上传服务器。",14,muted);button(access,"管理通知授权",()->new AlertDialog.Builder(this).setTitle("导航通知授权").setMessage("系统通知使用权范围较广；小马遥控只处理高德通知。请在系统页面手动授权，随时可以撤销。").setNegativeButton("取消",null).setPositiveButton("前往设置",(d,w)->{try{startActivity(new Intent(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS));}catch(Exception e){summary.setText("请在系统设置中搜索通知使用权");}}).show());
 LinearLayout more=card(content,panel);debug=text(more,"调试详情  ＋",16,muted);fields=text(more,"尚无通知",13,muted);fields.setVisibility(View.GONE);debug.setOnClickListener(v->{expanded=!expanded;fields.setVisibility(expanded?View.VISIBLE:View.GONE);debug.setText(expanded?"调试详情  −":"调试详情  ＋");});button(more,"恢复通知监听",()->NavigationListenerRecovery.request(this,true));button(root,"返回遥控",()->finish());}
 String meters(int n){return n<0?"--":n>=1000?String.format(java.util.Locale.US,"%.1f 公里",n/1000f):n+" 米";}
 final Runnable poll=new Runnable(){public void run(){boolean requested=NavigationNotificationService.savedEnabled(NavigationNotificationActivity.this);NavigationLink.Transport link=NavigationLink.transport;boolean connected=link!=null&&link.available();NavigationNotice n=NavigationNotificationService.latest;boolean fresh=NavigationNotificationService.fresh();
 state.setText(!requested?"同步已关闭":!NavigationNotificationService.listening?(NavigationListenerRecovery.granted?"通知监听未连接":"需要通知授权"):!connected?"等待设备蓝牙连接":!NavigationNotificationService.forwarding?"同步已暂停":NavigationNotificationService.deliveryIssue?"等待重新同步":fresh?(SystemClock.elapsedRealtime()-NavigationNotificationService.seenAt>=15000?"已连接 · 指引未变化":"已连接 · 正在同步"):"已连接 · 等待新指引");summary.setText(!NavigationNotificationService.listening?NavigationListenerRecovery.status:connected?(NavigationNotificationService.deliveryIssue?NavigationNotificationService.status:"手机负责导航，设备显示与播报"):"返回遥控首页连接你的设备");updating=true;forward.setChecked(requested);updating=false;arrow.direction=fresh?n.turn:7;arrow.invalidate();String[] labels={"继续直行","向左转","向右转","左前方","右前方","前方掉头","已到达","请以手机指引为准"};distance.setText(fresh?meters(n.distance):"--");turn.setText(fresh?labels[n.turn]:"等待新的导航通知");road.setText(fresh?NavigationFields.road(n.text):"在高德开始导航后自动更新");remaining.setText(fresh?"剩余 "+meters(n.remaining)+"  ·  "+(n.seconds<0?"--":n.seconds/60)+" 分钟":"剩余 --  ·  -- 分钟");background.setText(NavigationKeepAliveService.running?"● 后台同步服务运行中":"后台服务未运行，连接蓝牙后可开启");fields.setText("应用版本：0.5.6\n监听恢复："+NavigationListenerRecovery.status+"\n"+NavigationNotificationService.diagnostics()+"\n"+NavigationNotificationService.status+"\n\n"+NavigationNotificationService.preview);ui.postDelayed(this,1000);}};
 protected void onResume(){super.onResume();NavigationListenerRecovery.request(this,true);ui.removeCallbacks(poll);ui.post(poll);NavigationKeepAliveService.ensure(this);}protected void onPause(){ui.removeCallbacks(poll);super.onPause();}protected void onDestroy(){ui.removeCallbacksAndMessages(null);super.onDestroy();}
 static class Arrow extends View{int direction=7;Paint p=new Paint(3);Arrow(Context c){super(c);}protected void onDraw(Canvas c){super.onDraw(c);p.setColor(0xff62e7c0);p.setStrokeWidth(13);p.setStrokeCap(Paint.Cap.ROUND);p.setStyle(Paint.Style.STROKE);c.save();c.translate(getWidth()/2f,getHeight()/2f);float k=getHeight()/160f;c.scale(k,k);Path a=new Path();if(direction==7){p.setStrokeWidth(5);c.drawRoundRect(-24,-42,24,42,8,8,p);}else if(direction==6){a.moveTo(-35,0);a.lineTo(-7,30);a.lineTo(40,-30);c.drawPath(a,p);}else{if(direction==1)c.rotate(-90);if(direction==2)c.rotate(90);if(direction==3)c.rotate(-45);if(direction==4)c.rotate(45);if(direction==5)c.rotate(180);a.moveTo(0,48);a.lineTo(0,-48);a.moveTo(-30,-18);a.lineTo(0,-48);a.lineTo(30,-18);c.drawPath(a,p);}c.restore();}}
